(x, y, t) => {
  const sources = [
    [120 + Math.sin(t*0.5)*80, 60 + Math.cos(t*0.35)*40],
    [360 + Math.cos(t*0.45)*90, 60 + Math.sin(t*0.55)*35],
    [240 + Math.sin(t*0.3+1)*120, 120 + Math.cos(t*0.4)*70],
    [80 + Math.cos(t*0.6+2)*60, 180 + Math.sin(t*0.5)*40],
    [400 + Math.sin(t*0.4+3)*70, 180 + Math.cos(t*0.45)*45]
  ];
  const freqs = [0.07, 0.09, 0.055, 0.085, 0.065];
  const speeds = [2.0, 1.8, 2.4, 1.6, 2.2];
  const phases = [0, 1.2, 2.5, 0.8, 3.1];
  let act = 0, inh = 0;
  for (let i = 0; i < 5; i++) {
    const dx = x - sources[i][0], dy = y - sources[i][1];
    const d = Math.sqrt(dx*dx + dy*dy);
    const w = Math.sin(d * freqs[i] - t * speeds[i] + phases[i]);
    act += w;
    for (let j = i+1; j < 5; j++) {
      const dx2 = x - sources[j][0], dy2 = y - sources[j][1];
      const d2 = Math.sqrt(dx2*dx2 + dy2*dy2);
      inh += Math.sin((d + d2) * 0.03 - t * 1.2) * 0.3;
    }
  }
  act /= 5;
  const wx = Math.sin(x*0.02 + t*0.6) * Math.cos(y*0.015 + t*0.4);
  const wy = Math.cos(x*0.018 - t*0.5) * Math.sin(y*0.022 + t*0.35);
  const warpX = x + act * 18 + wx * 8;
  const warpY = y + inh * 18 + wy * 8;
  const cx = 240, cy = 120;
  const wdx = warpX - cx, wdy = warpY - cy;
  const wd = Math.sqrt(wdx*wdx + wdy*wdy);
  const wa = Math.atan2(wdy, wdx);
  const spiral = Math.sin(wd*0.035 - wa*3 + t*1.8);
  const ring = Math.sin(wd*0.06 - t*2.5) * Math.cos(wa*5 - t*0.3);
  const micro = Math.sin(warpX*0.12 + warpY*0.08 + t*2) * Math.sin(warpX*0.07 - warpY*0.11 - t*1.5) * 0.2;
  const reaction = Math.tanh((act - inh*0.7 + spiral*0.4 + ring*0.3 + micro) * 2.8);
  const v = reaction * 0.5 + 0.5;
  const pal = [
    [8, 18, 58], [15, 65, 95], [25, 140, 135],
    [75, 190, 160], [220, 195, 80], [235, 140, 65],
    [200, 70, 70], [120, 35, 85], [45, 20, 70], [8, 18, 58]
  ];
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;
  const depth = 0.78 + Math.sin(reaction * Math.PI * 1.5) * 0.22;
  const shimmer = 1 + Math.sin(wd*0.1 - t*4) * 0.06 * (1 - Math.abs(reaction));
  const lum = depth * shimmer;
  return [
    Math.min(255, (pal[i][0] + (pal[i+1][0]-pal[i][0])*f) * lum) | 0,
    Math.min(255, (pal[i][1] + (pal[i+1][1]-pal[i][1])*f) * lum) | 0,
    Math.min(255, (pal[i][2] + (pal[i+1][2]-pal[i][2])*f) * lum) | 0
  ];
}
